l","bound_author_id":921300021,"text":"De vier kinderen Pevensie worden onverwacht teruggebracht naar Narnia, maar herkennen het land nauwelijks. Hun vroegere kasteel is vervallen en de sprekende dieren worden onderdrukt door koning Miraz. Van de dwerg Trumpkin horen ze wat er sinds hun vertrek is gebeurd. Prins Caspian zoekt steun om de heersende macht te weerstaan. De kinderen raken opnieuw betrokken bij een strijd om de toekomst van een wereld die zonder hen verder is gegaan.","source_type":"official_catalog","source_name":"Bureau ISBN; oorspronkelijke gecontroleerde samenvatting","source_url":"https://metadata.isbn.nl/1423229/prins-caspian.html","provenance":"original_source_reviewed_summary","review_status":"approved","reviewed_at":"2026-11-01T14:24:00Z","review_batch":"nl006-reviewed-batch-01-20261101","evidence":[{"url":"https://metadata.isbn.nl/1423229/prins-caspian.html","sha256":"adda16c646268711aa1711ed2c74e8a4140a8f2415b81b415d83968c2b746039","checkedAt":"2026-11-01T13:15:12.174Z","fact":"Hardback ISBN 9789026610592 verschijningsdatum 01/01/2001 NUR 283 Fictie 10-12 jaar imprint Callenbach uitgever VBK Media taal Nederlands","sourceAuthors":"C.S. Lewis , Chris Staples Lewis","identityNote":"Same canonical Work, translation attached to existing identity; no author/Work merge."}]}},{"relation":"catalog_edition_metadata","ref":"metadata:9789024558704","key":{"edition_id":977200014},"before":null,"after":{"edition_id":977200014,"work_id":977100007,"bound_author_id":8800015,"bound_title":"Mes van dromen","bound_language":"dut","bound_isbn13":"9789024558704","format":"hardcover","cover_url":"https://metadata.isbn.nl/ie_fcache/0000214261_Mes_van_dromen_0_0.jpg","card_cover_url":null,"evidence_url":"https://metadata.isbn.nl/479822/mes-van-dromen.html","review_status":"approved","reviewed_at":"2026-11-01T14:24:00Z","review_batch":"nl006-reviewed-batch-01-20261101","evidence":[{"url":"https://metadata.isbn.nl/479822/mes-van-dromen.html","sha256":"59cd1e1afdb31305276b5c95c3e13c71fd966bb39f74566d287eefcb93fa1e11","checkedAt":"2026-11-01T13:15:14.357Z","fact":"Hardback ISBN 9789024558704 verschijningsdatum 22/11/2006 NUR 334 Fantasy imprint Luitingh uitgever Luitingh-Sijthoff B.V., Uitgeverij taal Nederlands","sourceAuthors":"Robert Jordan","identityNote":"Same canonical Work, translation attached to existing identity; no author/Work merge."},{"url":"https://metadata.isbn.nl/ie_fcache/0000214261_Mes_van_dromen_0_0.jpg","sha256":"f0edc0ec82f317003a0e94ca4e658abef1feda2d3d9dd11205fd4c8dae60de66","bytes":87151,"checkedAt":"2026-11-01T13:17:07.093Z","fact":"Exact ISBN block image + human visual title/author review, sheet1"}]}},{"relation":"catalog_work_descriptions","ref":"description:2179","key":{"work_id":977100007,"language":"nl"},"before":null,"after":{"work_id":977100007,"language":"nl","bound_author_id":8800015,"text":"De naderende Laatste Slag zet de landen en hoofdpersonen van Het Rad des Tijds steeds verder onder druk. Rhand Altor probeert zijn strijd tegen de Duistere te verenigen met de noodzaak een bestand met de Seanchanen te bereiken. Ondertussen volgen Perijn, Mart, Elayne en Egwene hun eigen gevaarlijke wegen. Militaire dreiging en interne verdeeldheid maken het moeilijk de krachten te verzamelen die voor de komende confrontatie nodig zijn.","source_type":"official_catalog","source_name":"Bureau ISBN; oorspronkelijke gecontroleerde samenvatting","source_url":"https://metadata.isbn.nl/479822/mes-van-dromen.html","provenance":"original_source_reviewed_summary","review_status":"approved","reviewed_at":"2026-11-01T14:24:00Z","review_batch":"nl006-reviewed-batch-01-20261101","evidence":[{"url":"https://metadata.isbn.nl/479822/mes-van-dromen.html","sha256":"59cd1e1afdb31305276b5c95c3e13c71fd966bb39f74566d287eefcb93fa1e11","checkedAt":"2026-11-01T13:15:14.357Z","fact":"Hardback ISBN 9789024558704 verschijningsdatum 22/11/2006 NUR 334 Fantasy imprint Luitingh uitgever Luitingh-Sijthoff B.V., Uitgeverij taal Nederlands","sourceAuthors":"Robert Jordan","identityNote":"Same canonical Work, translation attached to existing identity; no author/Work merge."}]}},{"relation":"catalog_edition_metadata","ref":"metadata:9789024594719","key":{"edition_id":977200016},"before":null,"after":{"edition_id":977200016,"work_id":977100008,"bound_author_id":8800015,"bound_title":"Het Licht van Weleer","bound_language":"dut","bound_isbn13":"9789024594719","format":"paperback","cover_url":"https://metadata.isbn.nl/ie_fcache/0000034930_Het_licht_van_weleer_0_0.jpg","card_cover_url":null,"evidence_url":"https://metadata.isbn.nl/161846/het-licht-van-weleer.html","review_status":"approved","reviewed_at":"2026-11-01T14:24:00Z","review_batch":"nl006-reviewed-batch-01-20261101","evidence":[{"url":"https://metadata.isbn.nl/161846/het-licht-van-weleer.html","sha256":"a2ead2a56f7d2b3a54048db20cc81ac19941825579ff2289f92539b0bac08921","checkedAt":"2026-11-01T13:15:16.452Z","fact":"Paperback ISBN 9789024594719 verschijningsdatum 23/05/2013 NUR 334 Fantasy imprint Luitingh uitgever Luitingh-Sijthoff B.V., Uitgeverij taal Nederlands","sourceAuthors":"Robert Jordan , Brandon Sanderson","identityNote":"Same canonical Work, translation attached to existing identity; no author/Work merge."},{"url":"https://metadata.isbn.nl/ie_fcache/0000034930_Het_licht_van_weleer_0_0.jpg","sha256":"cb0089408a0df111d238f4145be209a86c395efe2c805ad27c7866050b640635","bytes":19791,"checkedAt":"2026-11-01T13:17:08.991Z","fact":"Exact ISBN block image + human visual title/author review, sheet1"}]}},{"relation":"catalog_work_descriptions","ref":"description:2187","key":{"work_id":977100008,"language":"nl"},"before":null,"after":{"work_id":977100008,"language":"nl","bound_author_id":8800015,"text":"De vorsten van de grote naties verzamelen zich op de Akker van Merrilor, waar Rhand Altor hun steun nodig heeft voor de confrontatie met de Duistere. Zijn plannen roepen echter twijfel op, ook bij mensen die hem goed kennen. De mogelijkheid dat hij de zegels van de gevangenis van de Duistere verbreekt, verdeelt zijn medestanders. Dit afsluitende deel brengt de strijd om vertrouwen, samenwerking en het voortbestaan van de wereld samen.","source_type":"official_catalog","source_name":"Bureau ISBN; oorspronkelijke gecontroleerde samenvatting","source_url":"https://metadata.isbn.nl/161846/het-licht-van-weleer.html","provenance":"original_source_reviewed_summary","review_status":"approved","reviewed_at":"2026-11-01T14:24:00Z","review_batch":"nl006-reviewed-batch-01-20261101","evidence":[{"url":"https://metadata.isbn.nl/161846/het-licht-van-weleer.html","sha256":"a2ead2a56f7d2b3a54048db20cc81ac19941825579ff2289f92539b0bac08921","checkedAt":"2026-11-01T13:15:16.452Z","fact":"Paperback ISBN 9789024594719 verschijningsdatum 23/05/2013 NUR 334 Fantasy imprint Luitingh uitgever Luitingh-Sijthoff B.V., Uitgeverij taal Nederlands","sourceAuthors":"Robert Jordan , Brandon Sanderson","identityNote":"Same canonical Work, translation attached to existing identity; no author/Work merge."}]}},{"relation":"catalog_edition_metadata","ref":"metadata:9789056724535","key":{"edition_id":977200018},"before":null,"after":{"edition_id":977200018,"work_id":977100009,"bound_author_id":928301086,"bound_title":"Het boek Henry","bound_language":"dut","bound_isbn13":"9789056724535","format":"hardcover","cover_url":"https://metadata.isbn.nl/ie_fcache/0000015478_Het_boek_Henry_0_0.jpg","card_cover_url":null,"evidence_url":"https://metadata.isbn.nl/76895/het-boek-henry.html","review_status":"approved","reviewed_at":"2026-11-01T14:24:00Z","review_batch":"nl006-reviewed-batch-01-20261101","evidence":[{"url":"https://metadata.isbn.nl/76895/het-boek-henry.html","sha256":"0bb7dc1c15a409a73e59f2f07b9bac87c004d53f412cd81cc56dacc027537efa","checkedAt":"2026-11-01T13:15:18.523Z","fact":"Hardback ISBN 9789056724535 verschijningsdatum 04/09/2012 NUR 302 Vertaalde literaire roman, novelle imprint A.W. Bruna Uitgevers uitgever Bruna Uitgevers B.V., A.W. taal Nederlands","sourceAuthors":"Hilary Mantel","identityNote":"Same canonical Work, translation attached to existing identity; no author/Work merge."},{"url":"https://metadata.isbn.nl/ie_fcache/0000015478_Het_boek_Henry_0_0.jpg","sha256":"8aed96fe39b39ce299ef04abd9345ef42650a8fdc27248f4420ad5c6132b39d1","bytes":87870,"checkedAt":"2026-11-01T13:17:10.860Z","fact":"Exact ISBN block image + human visual title/author review, sheet1"}]}},{"relation":"catalog_work_descriptions","ref":"description:2194","key":{"work_id":977100009,"language":"nl"},"before":null,"after":{"work_id":977100009,"language":"nl","bound_author_id":928301086,"text":"Thomas Cromwell probeert zijn positie aan het hof van Hendrik VIII te behouden terwijl het lot van Anne Boleyn steeds onzekerder wordt. Haar relatie met de koning raakt in een crisis en Cromwell krijgt opnieuw een beslissende rol in het uitvoeren van diens wensen. De roman volgt de korte periode van Annes neergang vanuit een machtswereld waarin persoonlijke belangen en politieke overleving voortdurend met elkaar verweven zijn.","source_type":"official_catalog","source_name":"Bureau ISBN; oorspronkelijke gecontroleerde samenvatting","source_url":"https://metadata.isbn.nl/76895/het-boek-henry.html","provenance":"original_source_reviewed_summary","review_status":"approved","reviewed_at":"2026-11-01T14:24:00Z","review_batch":"nl006-reviewed-batch-01-20261101","evidence":[{"url":"https://metadata.isbn.nl/76895/het-boek-henry.html","sha256":"0bb7dc1c15a409a73e59f2f07b9bac87c004d53f412cd81cc56dacc027537efa","checkedAt":"2026-11-01T13:15:18.523Z","fact":"Hardback ISBN 9789056724535 verschijningsdatum 04/09/2012 NUR 302 Vertaalde literaire roman, novelle imprint A.W. Bruna Uitgevers uitgever Bruna Uitgevers B.V., A.W. taal Nederlands","sourceAuthors":"Hilary Mantel","identityNote":"Same canonical Work, translation attached to existing identity; no author/Work merge."}]}},{"relation":"catalog_edition_metadata","ref":"metadata:9789463492775","key":{"edition_id":977200020},"before":null,"after":{"edition_id":977200020,"work_id":977100010,"bound_author_id":924300308,"bound_title":"De verloren erfgenaam","bound_language":"dut","bound_isbn13":"9789463492775","format":"hardcover","cover_url":"https://metadata.isbn.nl/ie_fcache/0000566144_De_verloren_erfgenaam_0_0.jpg","card_cover_url":null,"evidence_url":"https://metadata.isbn.nl/1573161/de-verloren-erfgenaam.html","review_status":"approved","reviewed_at":"2026-11-01T14:24:00Z","review_batch":"nl006-reviewed-batch-01-20261101","evidence":[{"url":"https://metadata.isbn.nl/1573161/de-verloren-erfgenaam.html","sha256":"ac14ac5f72e2c198f4d088b1d61034912c9fca860ea7ad3d357e3a4067738a50","checkedAt":"2026-11-01T13:58:39.014Z","fact":"Hardback ISBN 9789463492775 verschijningsdatum 07/09/2021 NUR 285 Fictie 15+ imprint Blossom Books uitgever Blossom Books B.V. taal Nederlands","sourceAuthors":"Jennifer Lynn Barnes","identityNote":"Same canonical Work, translation attached to existing identity; no author/Work merge."},{"url":"https://metadata.isbn.nl/ie_fcache/0000566144_De_verloren_erfgenaam_0_0.jpg","sha256":"ac51401e2f6c0477410e811ba4454544732c8fb4bea126c45302ac8b86913e6c","bytes":788060,"checkedAt":"2026-11-01T14:19:28.758Z","fact":"Exact ISBN block image + human visual title/author review, sheet1"}]}},{"relation":"catalog_work_descriptions","ref":"description:2208","key":{"work_id":977100010,"language":"nl"},"before":null,"after":{"work_id":977100010,"language":"nl","bound_author_id":924300308,"text":"Avery Grambs heeft onverwacht het vermogen van Tobias Hawthorne geërfd, maar weet nog altijd niet waarom hij juist haar koos. Met Jameson en Grayson om zich heen probeert zij te achterhalen hoe lang Hawthorne haar al in de gaten hield. De zoektocht maakt de familiegeschiedenis ingewikkelder in plaats van duidelijker. Terwijl Avery antwoorden zoekt, moet zij ook rekening houden met mensen die haar liever uit Hawthorne House zien verdwijnen.","source_type":"official_catalog","source_name":"Bureau ISBN; oorspronkelijke gecontroleerde samenvatting","source_url":"https://metadata.isbn.nl/1573161/de-verloren-erfgenaam.html","provenance":"original_source_reviewed_summary","review_status":"approved","reviewed_at":"2026-11-01T14:24:00Z","review_batch":"nl006-reviewed-batch-01-20261101","evidence":[{"url":"https://metadata.isbn.nl/1573161/de-verloren-erfgenaam.html","sha256":"ac14ac5f72e2c198f4d088b1d61034912c9fca860ea7ad3d357e3a4067738a50","checkedAt":"2026-11-01T13:58:39.014Z","fact":"Hardback ISBN 9789463492775 verschijningsdatum 07/09/2021 NUR 285 Fictie 15+ imprint Blossom Books uitgever Blossom Books B.V. taal Nederlands","sourceAuthors":"Jennifer Lynn Barnes","identityNote":"Same canonical Work, translation attached to existing identity; no author/Work merge."}]}}],"bindings":[],"authorCorpora":[]}'::jsonb;a jsonb;b jsonb;actual jsonb;oldrow jsonb;nextrow jsonb;k jsonb;kv record;ids jsonb:='{}';cols text;vals text;v_id bigint;i integer:=0;n integer;begin
 for b in select value from jsonb_array_elements(payload->'bindings') loop
  select to_jsonb(w) into actual from public.works w where id=(b->'work'->>'id')::bigint;
  if actual is distinct from b->'work' and not exists(select 1 from jsonb_array_elements(payload->'actions') p where p->>'relation'='works' and p->'key'=jsonb_build_object('id',(b->'work'->>'id')::bigint) and actual=p->'after') then raise exception 'Work preflight drift';end if;
  select to_jsonb(t) into actual from public.authors t where id=(b->'author'->>'id')::bigint;
  if actual is distinct from b->'author' then raise exception 'Author preflight drift';end if;
 end loop;
 for b in select value from jsonb_array_elements(payload->'authorCorpora') loop
  select coalesce(jsonb_agg(to_jsonb(w) order by id),'[]') into actual from public.works w where author_id=(b->>'author_id')::bigint and not exists(select 1 from jsonb_array_elements(payload->'actions') p where p->>'relation'='works' and p->'before'='null' and w.native_identity_key=p->'after'->>'native_identity_key');
  select coalesce(jsonb_agg(to_jsonb(jsonb_populate_record(null::public.works,value)) order by (value->>'id')::bigint),'[]') into oldrow from jsonb_array_elements(b->'rows');
  select coalesce(jsonb_agg(to_jsonb(jsonb_populate_record(null::public.works,coalesce((select p->'after' from jsonb_array_elements(payload->'actions') p where p->>'relation'='works' and p->'before'<>'null' and p->'key'=jsonb_build_object('id',(v.value->>'id')::bigint)),v.value))) order by (v.value->>'id')::bigint),'[]') into nextrow from jsonb_array_elements(b->'rows') v;
  if actual is distinct from oldrow and actual is distinct from nextrow then raise exception 'New Work author corpus drift; repeat identity review';end if;
 end loop;
 for a in select value from jsonb_array_elements(payload->'actions') loop
  i:=i+1;k:=a->'key';nextrow:=a->'after';oldrow:=a->'before';
  if a->>'relation' not in ('authors','works','editions','catalog_work_descriptions','catalog_edition_metadata') then raise exception 'Unreviewed relation';end if;
  for kv in select * from jsonb_each(nextrow) loop
   if jsonb_typeof(kv.value)='string' and left(kv.value#>>'{}',1)='@' then
    if not ids ? substring(kv.value#>>'{}',2) then raise exception 'Unresolved parent reference';end if;
    nextrow:=jsonb_set(nextrow,array[kv.key],ids->substring(kv.value#>>'{}',2));
   end if;
  end loop;
  for kv in select * from jsonb_each(k) loop
   if jsonb_typeof(kv.value)='string' and left(kv.value#>>'{}',1)='@' then k:=jsonb_set(k,array[kv.key],ids->substring(kv.value#>>'{}',2));end if;
  end loop;
  execute format('select to_jsonb(t) from public.%I t where to_jsonb(t) @> $1 for update',a->>'relation') into actual using k;
  if oldrow<>'null'::jsonb then
   execute format('select to_jsonb(jsonb_populate_record(null::public.%I,$1))',a->>'relation') into oldrow using oldrow;
   execute format('select to_jsonb(jsonb_populate_record(null::public.%I,$1))',a->>'relation') into nextrow using nextrow;
   if actual is not distinct from nextrow then continue;end if;
   if actual is distinct from oldrow then raise exception 'Changed existing row in % at action %',a->>'relation',i;end if;
   select string_agg(format('%I=(jsonb_populate_record(null::public.%I,$1)).%I',key,a->>'relation',key),',') into cols from jsonb_each(nextrow) where value is distinct from oldrow->key;
   execute format('update public.%I t set %s where to_jsonb(t) @> $2 returning to_jsonb(t)',a->>'relation',cols) into actual using nextrow,k;
   insert into catalog_release_receipt values(i,a->>'relation',k,oldrow,actual);
  elsif actual is not null then
   if a->>'relation' in ('catalog_work_descriptions','catalog_edition_metadata') then
    execute format('select to_jsonb(jsonb_populate_record(null::public.%I,$1))',a->>'relation') into nextrow using nextrow;
    if actual is distinct from nextrow then raise exception 'Existing reviewed presentation differs; never overwrite';end if;
   elsif not actual @> nextrow then raise exception 'Existing natural identity differs';end if;
  else
   if a->>'relation'='editions' and exists(select 1 from public.editions e where (nextrow->>'isbn_13' is not null and regexp_replace(coalesce(e.isbn_13,''),'[-[:space:]]','','g')=nextrow->>'isbn_13') or (nextrow->>'isbn_10' is not null and upper(regexp_replace(coalesce(e.isbn_10,''),'[-[:space:]]','','g'))=nextrow->>'isbn_10') or (nextrow->>'open_library_edition_id' is not null and e.open_library_edition_id=nextrow->>'open_library_edition_id')) then raise exception 'Global edition identity collision';end if;
   select string_agg(format('%I',key),',' order by key),string_agg(format('(jsonb_populate_record(null::public.%I,$1)).%I',a->>'relation',key),',' order by key) into cols,vals from jsonb_each(nextrow);
   execute format('insert into public.%I(%s) select %s returning to_jsonb(%I)',a->>'relation',cols,vals,a->>'relation') into actual using nextrow;
   insert into catalog_release_receipt values(i,a->>'relation',k,null,actual);
  end if;
  if actual ? 'id' then ids:=jsonb_set(ids,array[a->>'ref'],actual->'id');end if;
 end loop;
 select count(*) into n from catalog_release_receipt;
 if n not in (0,20) then raise exception 'Partial install/replay; expected zero or all actions, got %',n;end if;
end;$release$;
